// 工具回执正文的**唯一取料口**（2026-10-23 实测出来的两半缺陷）。
//
// 契约缺口：`base.ts` 的 `ToolResult.output: string` 只约束**我们自己的**工具；插件工具、MCP 工具、
// 脚本化工具是运行期才拿到的，`{ok:true}`（缺 output）、`output:null`、`output:{…}` 都真实出现
// （那条接口管不到跨进程边界）。旧实现把 `result.output` 当字符串直接用：
//   ① `stuck.ts#stuckObservationOf` 直接 `.slice` ⇒ `TypeError: … (reading 'slice')` **把整轮任务打死**；
//   ② 就算绕过崩溃，`undefined + ""` 也会落成字面量 `"undefined"` —— 模型拿到一条"有回执但读不懂"的
//      tool_result，比明说"这条回执没有正文"更坏。
// 所以取料只此一处，两个出口（落盘正文 / 卡死比对的观察串）都从它取，免得修一处漏一处。
//
// 三条口径：
//  - 字符串**逐字不变**（不为了安全把正常输出包一层）；
//  - 真空串仍是空串（"真的没输出"是一个事实，不许被顶替成占位符）；
//  - 缺失 / null / 对象 / 空串必须**互相分得开**（否则卡死判定会把它们当成"拿到了相同结果"）。

/** 循环引用安全的 JSON 摘要（**不许抛**：参数里有环时 JSON.stringify 直接抛 TypeError）。
 *  环处换成显式占位（与脱敏面同一口径："[循环引用]"），既不炸也不静默丢字段。
 *  迁自 `stuck.ts`（动作摘要与回执正文共用同一份口径，不造第二套）。 */
export function safeJsonSummary(value: unknown, seen: WeakSet<object> = new WeakSet()): string {
  try {
    return JSON.stringify(value, (_key, v: unknown) => {
      if (typeof v === "object" && v !== null) {
        if (seen.has(v)) return "[循环引用]";
        seen.add(v);
      }
      return v;
    }) ?? "";
  } catch {
    // 兜底：带 getter 的对象、Proxy 陷阱等 stringify 也可能抛——摘要面不许因此炸掉整轮。
    return "[无法序列化]";
  }
}

/** 工具返回值的 `output` → 给模型看的那串字（`unknown`：跨进程边界回来的一切都可能）。 */
export function toolOutputText(output: unknown): string {
  // 正常路径：自己的工具都走这里，逐字原样（反向哨兵钉着这条）。
  if (typeof output === "string") return output;
  // 缺字段 / null：说清"这条回执没有正文"，而不是让 `undefined` 冒充一份真实输出。
  // 两者措辞分开：缺字段＝生产者没按契约填这一格；null＝生产者显式说了"没有值"。
  // 都不含 "undefined" 字样（那正是模型会当成正文去读的东西）。
  if (output === undefined) {
    return "[没有正文] 工具的返回体缺少 output 字段（插件 / MCP / 脚本化工具的回执可能不带这一格）"
      + " ⇒ 这次调用有没有生效未知，需要就重跑或用别的探针确认盘上现状。";
  }
  if (output === null) {
    return "[没有正文] 工具的 output 为 null（显式的「没有值」，与空串「有值但为空」不是一回事）"
      + " ⇒ 这次调用没有交回正文，需要就重跑或换探针确认。";
  }
  // 对象 / 数组 / 数字 / 布尔…：序列化出来。`String(obj)` 会是 `[object Object]`，等于把回执扔了。
  const json = safeJsonSummary(output);
  if (json !== "") return json;
  // 序列化不出内容（函数、Symbol、带顶层环且 stringify 抛错后仍返回空等）：也给一条可读事实。
  return "[没有正文] 工具的 output 无法序列化成文本（类型 " + typeof output + "）。";
}

